// Ported from the Node app's Sequelize model PurchaseOrder (first generated by tools/gen-efcore.mjs).
using System.Text.Json.Nodes;
using System.Text.Json.Serialization;
using SchoolERP.Domain.Common;

namespace SchoolERP.Domain.Entities;

/// <summary>Table <c>purchase_orders</c>.</summary>
public class PurchaseOrder : AuditableEntity
{
    public int Id { get; set; }
    public int SupplierId { get; set; }
    public DateOnly OrderDate { get; set; }
    public DateOnly? ExpectedDate { get; set; }
    public string Status { get; set; } = "ordered";
    public DateOnly? ReceivedOn { get; set; }
    public string? Note { get; set; }
    public string? CreatedByName { get; set; }

    [JsonPropertyName("Supplier")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Supplier? Supplier { get; set; }
    [JsonIgnore]
    public ICollection<PurchaseOrderLine> PurchaseOrderLines { get; set; } = new List<PurchaseOrderLine>();
}
